<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#172033}h1{font-size:22px;margin:0 0 4px}.muted{color:#667085}.header{border-bottom:2px solid #0f766e;padding-bottom:14px;margin-bottom:18px}.meta{width:100%;margin:10px 0 18px}.meta td{padding:3px 0}table.orders{width:100%;border-collapse:collapse}th{background:#0f766e;color:#fff;text-align:left}th,td{padding:8px;border:1px solid #d0d5dd}.total{margin-top:14px;text-align:right;font-weight:bold}.signatures{margin-top:65px;width:100%}.signatures td{width:50%;padding-right:45px}.line{border-top:1px solid #172033;margin-top:32px;padding-top:5px}</style></head><body><div class="header"><h1>Transfer Manifest</h1><div class="muted">{{ $manifest->manifest_number }} | Dispatch date: {{ now()->format('M d, Y') }}</div><div style="font-family:monospace;font-size:18px;margin-top:10px">*{{ $manifest->manifest_number }}*</div></div><table class="meta"><tr><td><strong>Origin hub:</strong> {{ $manifest->originHub->name }}</td><td><strong>Destination hub:</strong> {{ $manifest->destinationHub->name }}</td></tr></table><table class="orders"><thead><tr><th>#</th><th>AWB number</th><th>Sender</th><th>Recipient</th><th>Address</th><th>Weight (kg)</th></tr></thead><tbody>@foreach($orders as $index => $order)<tr><td>{{ $index + 1 }}</td><td>{{ $order->awb_number }}</td><td>{{ $order->sender_name }}</td><td>{{ $order->recipient_name }}</td><td>{{ $order->recipient_address }}</td><td>{{ number_format((float) $order->weight_kg, 2) }}</td></tr>@endforeach</tbody></table><div class="total">Total orders: {{ $orders->count() }} | Total weight: {{ number_format((float) $orders->sum('weight_kg'), 2) }} kg</div><table class="signatures"><tr><td><div class="line">Prepared by: {{ $manifest->generated_by }}</div></td><td><div class="line">Authorized signature</div></td></tr></table></body></html>